3	export function streaks(done: ReadonlySet<DayKey>, today: DayKey): { current: number; longest: number } {
4	  let current = 0;
5	  let cursor = today;
6	  if (!done.has(cursor)) cursor = addDays(today, -1); // today still open
7	  while (done.has(cursor)) {
8	    current++;
9	    cursor = addDays(cursor, -1);
10	  }
11	
12	  const keys = [...done].sort();
13	  let longest = 0;
14	  let run = 0;
15	  let prev: DayKey | null = null;
16	  for (const k of keys) {
17	    run = prev && addDays(prev, 1) === k ? run + 1 : 1;
18	    if (run > longest) longest = run;
19	    prev = k;
20	  }
21	  return { current, longest };
22	}
