13	export function moveInArray<T>(ids: T[], from: number, to: number): T[] {
14	  if (from < 0 || from >= ids.length || to < 0 || to >= ids.length || from === to) {
15	    return [...ids];
16	  }
17	  const next = [...ids];
18	  const [item] = next.splice(from, 1);
19	  next.splice(to, 0, item);
20	  return next;
21	}
